deepml specialized 0.3
module corpus.deepml_specialized.example_02251
policy deterministic
policy no_network
domain finance {
  unit InputUnit = base("input")
  tensor x: f64<InputUnit>[8,9]
  operator calibrate(x) -> Tensor pure deterministic
  calibration C02251 { method: bounded_least_squares tolerance: 1e-6 }
  constraint PhysicalBounds { min: 0 max: 551 }
  validate x with [calibrate, C02251, PhysicalBounds]
}
assert domain.semantic_hash == "invalid-02251"

